    }
  }
  if (mode === "flap") {   // a plate rising from the wing's trailing edge, across the wing's span
    for (let j = 0; j < ny; j++) {
      let i = nx - 1; while (i >= 0 && !(wTop[j * nx + i] > -Infinity)) i--;
      if (i < 0) continue;
